cd multicode/obelisk/full; cat > core/gifts.mjs <<'EOF'
// spec: gifts
// Подарки (хлопушки): бросок подарка и операции Blue Cow / хлопушек. Код по спеке oracle/specs/gifts.md (правила 1–12).

export function makeGifts(data) {
  const C = data.constants;
  const tab = (name) => {
    const t = data.tables[name];
    return t.rows.map((r) => Object.fromEntries(t.columns.map((c, i) => [c, r[i]])));
  };
  const overrides = tab('overrides').sort((a, b) => a.k - b.k);
  const labels = tab('labels');
  const amounts = tab('amounts');
  const fixed = tab('fixed');
  const stickers = tab('stickers').sort((a, b) => a.order - b.order);
  const ops = Object.fromEntries(tab('ops').map((r) => [r.op, r]));

  const inRange = (v, from, to) => from <= v && (to === null || v <= to);

  // шанс «a из n»: U = (hi · 2^32 + lo) mod 2^63, выпал, если (U mod n) + 1 ≤ a; ровно 2 слова
  function chance(g, a, n) {
    const lo = BigInt(g.u32());
    const hi = BigInt(g.u32());
    const u = ((hi << 32n) | lo) & ((1n << 63n) - 1n);
    return u % BigInt(n) + 1n <= BigInt(a);
  }

  // правило 1
  function round(x, kind) {
    if (kind === 'none') return x;
    if (kind === 'half-up') return Math.floor(x + 0.5);
    if (kind === 'half-down') return Math.ceil(x - 0.5);
    const f = Math.floor(x), d = x - f;
    if (d < 0.5) return f;
    if (d > 0.5) return f + 1;
    return f % 2 === 0 ? f : f + 1;
  }

  const gateOpen = (o, state) => {
    const v = o.gate === 'blackHole' ? state.blackHole : state.obelisk;
    return inRange(v, o.from, o.to);
  };

  function roll(state, rng, builtin) {
    const ob = state.obelisk;
    let t = rng.u32() % C['base.count'];
    let skin = -1;
    let nested = false;
    for (const o of overrides) {
      const hit = chance(rng, o.a, o.n);
      if (!hit || !gateOpen(o, state)) continue;
      if (o.kind === 'type') {
        t = o.type;
        skin = -1;
      } else if (o.kind === 'skin') {
        const free = [];
        for (let i = 0; i < C['skin.count']; i++) if (!state.skinsOwned[i]) free.push(i);
        if (free.length) {
          t = o.type;
          skin = free[rng.u32() % free.length];
        } else {
          t = C['skin.fallbackType'];
          skin = -1;
        }
      } else if (o.kind === 'nested') {
        nested = true;
      }
    }
    if (nested && chance(rng, C['nested.a'], C['nested.n'])) {
      t = C['nested.type'];
      skin = -1;
    }

    const variant = t === C['fish.type'] && state.fishStarted ? 'fish' : 'base';
    const lab = labels.find((l) => l.type === t && l.variant === variant && inRange(ob, l.from, l.to));
    const res = {
      type: t,
      text: lab && lab.text !== null ? [lab.text] : [],
      xm: lab ? lab.xm : 'x',
      sprite: lab ? lab.sprite : null,
      index: lab && lab.index !== null ? lab.index : 0,
      amount: 0,
      skin: -1,
      skinNew: false,
    };

    if (t === C['sticker.type']) {
      const list = stickers.filter((s) => s.gate === 'none'
        || (s.gate === 'obelisk' && ob >= s.min) || (s.gate === 'blackHole' && state.blackHole >= s.min));
      const s = list[rng.u32() % list.length];
      res.index = s.sticker;
      res.text = [s.text, C['sticker.suffix']];
    }
    if (t === C['skin.type'] && skin >= 0) {
      res.index = skin;
      res.skin = skin;
      res.skinNew = true;
    }
    if (t === C['lobster.type'] && chance(builtin, C['lobster.a'], C['lobster.n'])) {
      res.text = [C['lobster.rareText']];
    }

    const fx = fixed.find((f) => f.type === t);
    if (fx) {
      res.amount = fx.amount;
    } else if (t === C['fuel.type']) {
      const u = rng.u32();
      res.amount = Math.max(C['fuel.min'], C['fuel.k'] * ob + C['fuel.b'] + C['fuel.lo'] + (u % (C['fuel.hi'] - C['fuel.lo'] + 1)));
    } else {
      const row = amounts.find((r) => r.type === t && r.variant === variant && inRange(ob, r.from, r.to));
      let lo = row.lo, hi = row.hi;
      if (t === C['idol.type']) {
        const m = 1 + state.archAscension;
        lo *= m;
        hi *= m;
      }
      res.amount = lo + (rng.u32() % (hi - lo + 1));
    }
    return res;
  }

  function apply(world, op, n, obelisk) {
    const r = ops[op];
    const d = r.sign * round(n, obelisk <= C['round.obelisk'] ? r.low : r.high);
    if (r.target === 'blueCows') {
      world.blueCows += d;
      world.blueCowsCheck += d;
    } else {
      world.crackers += d;
      world.crackersCheckA += d;
      world.crackersCheckB += d;
    }
  }

  return { roll, apply };
}
EOF
