cd multicode/obelisk/full; cat > /tmp/probe_g.mjs <<'EOF'
import { check } from 'multicode/obelisk/full/oracle/gifts839/check839.mjs';
import { makeGifts } from 'multicode/obelisk/full/core/gifts.mjs';
const seen = [];
const make = (d) => { const g = makeGifts(d); return { apply: g.apply, roll: (s, r, b) => { const x = g.roll(s, r, b); seen.push({ ob: s.obelisk, bh: s.blackHole, t: x.type, idx: x.index }); return x; } }; };
const r = check({ make });
console.log(r.ok, r.control.ok);
const u = (f) => seen.filter(f).length;
console.log('type0@75', u(x => x.t === 0 && x.ob === 75), 'sticker@37/38', u(x => x.t === 29 && x.ob >= 37 && x.ob <= 38), 'sticker bh', u(x=>x.t===29&&x.bh>=1), 'ob59/60', u(x=>x.ob===59||x.ob===60), 'ob3/4', u(x=>x.ob===3||x.ob===4), 'bh1', u(x=>x.bh===1));
EOF
